describe('Request Timeout Error Handling', () => {
  beforeEach(() => {
    cy.visit('/api/data');
  });

  it('should display timeout error when request exceeds 10 seconds', () => {
    // Intercept the API call and delay the response
    cy.intercept('GET', '/api/data', (req) => {
      req.reply((res) => {
        res.delay(11000);
        res.send({
          statusCode: 200,
          body: { data: 'delayed response' }
        });
      });
    }).as('delayedRequest');

    // Trigger the API call
    cy.get('[data-testid="fetch-button"]').click();

    // Wait for the timeout error to be displayed
    cy.get('[data-testid="timeout-error-message"]')
      .should('be.visible')
      .should('contain', 'Request timed out');

    // Verify the error state is visible
    cy.get('[data-testid="error-state-icon"]')
      .should('be.visible')
      .have.class('error');

    // Verify the original data is not displayed
    cy.get('[data-testid="data-display"]')
      .should('not.exist');

    // Verify retry button is available
    cy.get('[data-testid="retry-button"]')
      .should('be.visible');
  });

  it('should handle timeout gracefully and allow retry', () => {
    // Intercept the API call and delay the response
    cy.intercept('GET', '/api/data', (req) => {
      req.reply((res) => {
        res.delay(12000);
        res.send({
          statusCode: 200,
          body: { data: 'delayed response' }
        });
      });
    }).as('delayedRequest');

    // Trigger the API call
    cy.get('[data-testid="fetch-button"]').click();

    // Verify timeout error appears
    cy.get('[data-testid="timeout-error-message"]')
      .should('be.visible')
      .should('contain', 'Request timed out');

    // Click retry button
    cy.get('[data-testid="retry-button"]').click();

    // Intercept the retry request and respond immediately
    cy.intercept('GET', '/api/data', {
      statusCode: 200,
      body: { data: 'successful response' }
    }).as('retryRequest');

    // Wait for the successful retry
    cy.wait('@retryRequest');

    // Verify timeout error is cleared
    cy.get('[data-testid="timeout-error-message"]')
      .should('not.exist');

    // Verify data is now displayed
    cy.get('[data-testid="data-display"]')
      .should('be.visible')
      .should('contain', 'successful response');

    // Verify error state is cleared
    cy.get('[data-testid="error-state-icon"]')
      .should('not.exist');
  });
});
